import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/defaultAccount.dart'
    as da;
import 'package:semi_design_flutter/src/monaco/base/common/policy.dart' as pol;

void main() {
  // defaultAccount.ts is type-only: zero runtime exports in TS truth.
  test('defaultAccount types are carryable (TS exports nothing at runtime)', () {
    expect(_truthDefaultAccountExports, isEmpty);
    // Representative construction proves the 1:1 carriers are usable.
    final quotas = da.ILegacyQuotas(3, 5);
    final snap = da.IQuotaSnapshotData(
      overage_count: 1,
      overage_entitlement: 2,
      overage_permitted: true,
      percent_remaining: 50,
      unlimited: false,
    );
    final ent = da.IEntitlementsData(
      access_type_sku: 'free',
      chat_enabled: true,
      assigned_date: '2026-01-01',
      can_signup_for_limited: true,
      copilot_plan: 'free',
      organization_login_list: <String>['org'],
      analytics_tracking_id: 'aid',
      limited_user_quotas: quotas,
      quota_snapshots: da.IQuotaSnapshots(chat: snap),
    );
    expect(ent.quota_snapshots!.chat, same(snap));
    expect(ent.limited_user_quotas, same(quotas));

    final account = da.IDefaultAccount(
      authenticationProvider:
          da.IDefaultAccountAuthenticationProvider('a', 'A', false),
      accountName: 'name',
      sessionId: 'sid',
      enterprise: false,
      entitlementsData: ent,
    );
    expect(account.sessionId, 'sid');

    final policyData = da.IPolicyData(mcp: true, mcpAccess: 'allow_all');
    expect(policyData.mcp, isTrue);
    expect(da.ICopilotTokenInfo(sn: 'x').sn, 'x');
  });

  test('policy runtime exports match TS truth', () {
    final exports = List<String>.from(_truthPolicyExports)..sort();
    // Dart carries extra type classes; assert the three runtime constants exist.
    expect(exports, contains('LINUX_SYSTEM_POLICY_FILE_PATH'));
    expect(exports, contains('PolicyCategory'));
    expect(exports, contains('PolicyCategoryData'));
    expect(pol.LINUX_SYSTEM_POLICY_FILE_PATH,
        _truthLinuxPolicyPath);
  });

  test('PolicyCategory values match TS string enum', () {
    final expected = Map<String, String>.from(_truthPolicyCategory);
    expect(pol.PolicyCategory.Extensions, expected['Extensions']);
    expect(pol.PolicyCategory.IntegratedTerminal,
        expected['IntegratedTerminal']);
    expect(pol.PolicyCategory.InteractiveSession,
        expected['InteractiveSession']);
    expect(pol.PolicyCategory.Telemetry, expected['Telemetry']);
    expect(pol.PolicyCategory.Update, expected['Update']);
  });

  test('PolicyCategoryData keys and localized values match TS truth', () {
    final expected = Map<String, dynamic>.from(_truthCategoryData);
    expect(pol.PolicyCategoryData.length, expected.length);
    for (final entry in expected.entries) {
      final exp = Map<String, String>.from(entry.value as Map);
      final actual = pol.PolicyCategoryData[entry.key]!['name']!;
      expect(actual.key, exp['key'], reason: '${entry.key} key');
      expect(actual.value, exp['value'], reason: '${entry.key} value');
    }
  });
}

